test({ sr: 'broji sva pojavljivanja', en: 'counts all occurrences' }, () => {
  expect(countOccurrences([1, 2, 1, 1], 1)).toBe(3);
});
test({ sr: 'vrednost koje nema daje 0', en: 'a value that is missing gives 0' }, () => {
  expect(countOccurrences(['a', 'b'], 'c')).toBe(0);
});
test({ sr: 'prazan niz daje 0', en: 'an empty array gives 0' }, () => {
  expect(countOccurrences([], 'a')).toBe(0);
});

hiddenTests:
test('strict comparison: the number 1 and the text "1" are different', () => {
  expect(countOccurrences(['1', 1, '1'], '1')).toBe(2);
});
test('all elements are equal', () => {
  expect(countOccurrences(['a', 'a', 'a'], 'a')).toBe(3);
});
test('NaN is never counted', () => {
  expect(countOccurrences([NaN, 1], NaN)).toBe(0);
});
test('does not change the input', () => {
  const input = [1, 1];
  countOccurrences(input, 1);
  expect(input).toEqual([1, 1]);
});

