function countOccurrences(items, value) {
  let count = 0;
  let index = items.indexOf(value);
  while (index !== -1) {
    count++;
    index = items.indexOf(value, index + 1);
  }
  return count;
}

function countOccurrences(items, value) {
  return items.filter((item) => item === value).length;
}
